package main

import (
	"fmt"
	"os"
	"sort"
)

const appVersion = "v0.0.0-SNAPSHOT"

// commands maps the canonical subcommand name to its handler.
// Handler returns the exit code. stdout/stderr are written directly.
var commands = []subcommand{
	{Name: "check", Short: "run linter over specified targets", Run: runCheck},
	{Name: "doc", Short: "get installed checkers documentation", Run: runDoc},
	{Name: "help", Short: "shows help message", Run: runHelp},
	{Name: "version", Short: "shows version of the application", Run: runVersion},
}

type subcommand struct {
	Name  string
	Short string
	Run   func(args []string) int
}

func findCommand(name string) *subcommand {
	for i := range commands {
		if commands[i].Name == name {
			return &commands[i]
		}
	}
	return nil
}

// suggestCommand returns the closest command name by Levenshtein distance
// if at most 2 edits away; empty string otherwise.
func suggestCommand(name string) string {
	if name == "" {
		return ""
	}
	// Deterministic lookup: iterate commands in sorted order.
	sorted := make([]string, 0, len(commands))
	for _, c := range commands {
		sorted = append(sorted, c.Name)
	}
	sort.Strings(sorted)
	best := ""
	bestDist := -1
	for _, n := range sorted {
		d := editDistance(name, n)
		if d <= 2 && (bestDist == -1 || d < bestDist) {
			best = n
			bestDist = d
		}
	}
	return best
}

// editDistance returns the Levenshtein distance between a and b.
func editDistance(a, b string) int {
	ar := []rune(a)
	br := []rune(b)
	la, lb := len(ar), len(br)
	if la == 0 {
		return lb
	}
	if lb == 0 {
		return la
	}
	prev := make([]int, lb+1)
	curr := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		curr[0] = i
		for j := 1; j <= lb; j++ {
			cost := 1
			if ar[i-1] == br[j-1] {
				cost = 0
			}
			ins := curr[j-1] + 1
			del := prev[j] + 1
			sub := prev[j-1] + cost
			m := ins
			if del < m {
				m = del
			}
			if sub < m {
				m = sub
			}
			curr[j] = m
		}
		prev, curr = curr, prev
	}
	return prev[lb]
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "no args provided")
		return
	}
	cmd := os.Args[1]
	if cmd == "" {
		// Observed behaviour: empty command argument produces no output
		// and exits with status 0.
		return
	}
	if c := findCommand(cmd); c != nil {
		os.Exit(c.Run(os.Args[2:]))
	}
	// Unknown command with optional suggestion.
	suggestion := suggestCommand(cmd)
	if suggestion != "" {
		fmt.Printf("%q unknown command, did you mean %q?\n", cmd, suggestion)
	} else {
		fmt.Printf("%q unknown command\n", cmd)
	}
	fmt.Println(`Run "go-critic help" for usage.`)
	fmt.Fprintln(os.Stderr)
	fmt.Fprintf(os.Stderr, "no such command %q\n", cmd)
}

func runHelp(_ []string) int {
	fmt.Print(helpText())
	return 0
}

func helpText() string {
	const tmpl = `Usage:

    go-critic <command> [arguments...]

The commands are:

    check             run linter over specified targets
    doc               get installed checkers documentation
    help              shows help message
    version           shows version of the application

Version: %s

`
	return fmt.Sprintf(tmpl, appVersion)
}

