package main

import (
	"flag"
	"fmt"
	"os"
	"runtime"
	"sort"
	"strings"
)

// runCheck implements a minimal "check" subcommand that parses the same
// flag surface as the reference binary. It does not implement the actual
// Go source analysis but matches observable CLI semantics for enabled
// checker set resolution and flag parsing errors.
func runCheck(args []string) int {
	fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	// Register per-checker parameter flags (in sorted order to match output).
	registerCheckerParams(fs)

	// Common flags.
	_ = fs.Bool("checkGenerated", false, "whether to check generated files")
	_ = fs.Bool("checkTests", true, "whether to check test files")
	_ = fs.Int("concurrency", runtime.GOMAXPROCS(0),
		"how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
	_ = fs.String("cpuprofile", "", "write CPU profile to the specified file")
	disable := fs.String("disable", "", "comma-separated list of checkers to be disabled. Can include #tags")
	defaultEnableStr := strings.Join(defaultEnabled(), ",")
	enable := fs.String("enable", defaultEnableStr,
		"comma-separated list of enabled checkers. Can include #tags")
	enableAll := fs.Bool("enableAll", false,
		"identical to -enable with all checkers listed. If true, -enable is ignored")
	exitCode := fs.Int("exitCode", 1, "exit code to be used when lint issues are found")
	_ = fs.String("go", "", "select the Go version to target. Leave as string for the latest")
	_ = fs.String("memprofile", "", "write memory profile to the specified file")
	_ = fs.Bool("shorterErrLocation", true,
		"whether to replace error location prefix with $GOROOT and $GOPATH")
	verbose := fs.Bool("v", false, "whether to print output useful during linter debugging")

	if err := fs.Parse(args); err != nil {
		fmt.Fprintln(os.Stderr, "parse args:", err)
		return 1
	}

	selected := resolveCheckerSet(*enable, *disable, *enableAll, *verbose)
	if len(selected) == 0 {
		fmt.Fprintln(os.Stderr, "init checkers: empty checkers set selected")
		return 1
	}
	// Targets. We silently accept them and report nothing -
	// actual static analysis is out of scope for this reimplementation.
	_ = fs.Args()
	_ = exitCode
	return 0
}

// registerCheckerParams declares the per-checker parameter flags in the
// sorted order observed from the reference binary.
func registerCheckerParams(fs *flag.FlagSet) {
	fs.Bool("@captLocal.paramsOnly", true,
		"whether to restrict checker to params only")
	fs.Int("@commentedOutCode.minLength", 15,
		"min length of the comment that triggers a warning")
	fs.Bool("@elseif.skipBalanced", true,
		"whether to skip balanced if-else pairs")
	fs.Int("@hugeParam.sizeThreshold", 80,
		"size in bytes that makes the warning trigger")
	fs.Int("@ifElseChain.minThreshold", 2,
		"min number of if-else blocks that makes the warning trigger")
	fs.Int("@nestingReduce.bodyWidth", 5,
		"min number of statements inside a branch to trigger a warning")
	fs.Int("@rangeExprCopy.sizeThreshold", 512,
		"size in bytes that makes the warning trigger")
	fs.Bool("@rangeExprCopy.skipTestFuncs", true,
		"whether to check test functions")
	fs.Int("@rangeValCopy.sizeThreshold", 128,
		"size in bytes that makes the warning trigger")
	fs.Bool("@rangeValCopy.skipTestFuncs", true,
		"whether to check test functions")
	fs.String("@ruleguard.debug", "",
		"enable debug for the specified named rules group")
	fs.String("@ruleguard.disable", "",
		"comma-separated list of disabled groups or skip empty to enable everything")
	fs.String("@ruleguard.enable", "<all>",
		"comma-separated list of enabled groups or skip empty to enable everything")
	fs.String("@ruleguard.failOn", "",
		"Determines the behavior when an error occurs while parsing ruleguard files.\nIf flag is not set, log error and skip rule files that contain an error.\nIf flag is set, the value must be a comma-separated list of error conditions.\n* 'import': rule refers to a package that cannot be loaded.\n* 'dsl':    gorule file does not comply with the ruleguard DSL.")
